\text{Let the side length of the new cube be } x \text{ cm.} \\
\text{Volume of the new cube} &= x \text{ cm} \times x \text{ cm} \times x \text{ cm} = x^3 \text{ cm}^3 \\
\text{So, } x^3 = 27 \text{ cm}^3 \\
x &= \sqrt[3]{27} \text{ cm} \\
x &= 3 \text{ cm}
\end{align*}
